GRAMMAR_TOPICS=[g(*x) for x in [("pronouns","Personal pronouns","Use би, чи, тэр and бид in basic sentences.",["Би оюутан.","Тэр багш."]),("copula","Identity statements","Use байна and noun predicates for simple identity.",["Би оюутан байна.","Тэр багш байна."]),("negation","Negation","Use биш and үгүй for basic negatives.",["Би багш биш.","Энд хүн алга."]),("questions","Questions","Use юу, хаана and хэн for basic questions.",["Энэ юу вэ?","Чи хаана байна?"]),("possessive","Possession","Use -ын/-ийн and possessive forms for familiar ownership.",["Энэ миний ном.","Энэ Болдын гэр."]),("cases","Basic cases","Use common case endings for location and movement.",["Би сургуульд явна.","Би гэрт байна."]),("numbers","Numbers","Use basic numbers with familiar nouns.",["Надад хоёр ном байна.","Гурван хүн байна."]),("time","Time expressions","Talk about today and tomorrow.",["Өнөөдөр би ажиллана.","Маргааш би сургууль явна."])]]
