VOCABULARY_SETS=[v(*x) for x in [("greetings_a1","Greetings",[("Сайн байна уу","phrase","hello","Сайн байна уу!"),("Баярлалаа","phrase","thank you","Баярлалаа."),("Баяртай","phrase","goodbye","Баяртай!"),("нэр","noun","name","Миний нэр Болд.")]),("family_a1","Family",[("ээж","noun","mother","Миний ээж гэрт байна."),("аав","noun","father","Миний аав ажилладаг."),("ах","noun","older brother","Ах маань энд байна."),("дүү","noun","younger sibling","Дүү сургуульд явна.")]),("home_a1","Home",[("гэр","noun","home","Миний гэр том."),("өрөө","noun","room","Өрөө цэвэрхэн байна."),("ширээ","noun","table","Ном ширээн дээр байна."),("хаалга","noun","door","Хаалга нээлттэй байна.")]),("daily_a1","Daily life",[("өглөө","noun","morning","Өглөө би ажиллана."),("ажиллах","verb","work","Би ажиллана."),("явах","verb","go","Би сургууль явна."),("унтах","verb","sleep","Би орой унтана.")]),("food_a1","Food and shopping",[("ус","noun","water","Би ус хүсэж байна."),("талх","noun","bread","Би талх авна."),("цай","noun","tea","Би цай ууна."),("үнэ","noun","price","Энэ хэдэн төгрөг вэ?")]),("places_a1","Places and directions",[("дэлгүүр","noun","shop","Дэлгүүр ойрхон байна."),("сургууль","noun","school","Сургууль энд байна."),("баруун","noun","right","Баруун тийш яв."),("зүүн","noun","left","Зүүн тийш яв.")]),("communication_a1","Communication",[("туслах","verb","help","Надад туслаач."),("гуйя","phrase","please","Дахин хэлж өгнө үү, гуйя."),("ойлгох","verb","understand","Би ойлгохгүй байна."),("дахин","adverb","again","Дахин хэлнэ үү.")]),("review_a1","A1 review",[("өнөөдөр","adverb","today","Өнөөдөр би гэрт байна."),("маргааш","adverb","tomorrow","Маргааш би ажиллана."),("найз","noun","friend","Тэр миний найз."),("цаг","noun","time","Надад цаг байна.")])]]
