PHRASEBOOK_CATEGORIES=[p(*x) for x in [("greetings_a1","Greetings",[("Сайн байна уу!","greeting"),("Миний нэр Болд.","introducing yourself")]),("shopping_a1","Shopping",[("Энэ хэдэн төгрөг вэ?","asking price"),("Энийг авъя.","requesting an item")]),("directions_a1","Directions",[("Дэлгүүр хаана байна?","asking location"),("Баруун тийш яв.","giving directions")]),("help_a1","Help",[("Надад туслаач.","asking for help"),("Би ойлгохгүй байна.","clarification")])]]
